CREATE TABLE public.account_access (user_id uuid PRIMARY KEY, active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.account_access TO authenticated;
GRANT ALL ON public.account_access TO service_role;
ALTER TABLE public.account_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY account_own_read ON public.account_access FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.account_is_active(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.account_access WHERE user_id=_user_id AND NOT active) $$;
REVOKE ALL ON FUNCTION public.account_is_active(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.account_is_active(uuid) TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.account_is_active(_user_id) AND EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND (role=_role OR (role='super_admin'::public.app_role AND _role IN ('admin'::public.app_role,'editor'::public.app_role)))) $$;
CREATE TABLE public.invoice_sequences (user_id uuid NOT NULL, prefix text NOT NULL, last_value integer NOT NULL DEFAULT 0, PRIMARY KEY(user_id,prefix));
GRANT SELECT ON public.invoice_sequences TO authenticated;
GRANT ALL ON public.invoice_sequences TO service_role;
ALTER TABLE public.invoice_sequences ENABLE ROW LEVEL SECURITY;
CREATE POLICY sequence_own_read ON public.invoice_sequences FOR SELECT TO authenticated USING (user_id=auth.uid() AND public.account_is_active(auth.uid()));
CREATE TABLE public.invoice_businesses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), name text NOT NULL, data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.invoice_businesses TO authenticated;
GRANT ALL ON public.invoice_businesses TO service_role;
ALTER TABLE public.invoice_businesses ENABLE ROW LEVEL SECURITY;
CREATE POLICY business_own ON public.invoice_businesses FOR ALL TO authenticated USING (user_id=auth.uid() AND public.account_is_active(auth.uid())) WITH CHECK (user_id=auth.uid() AND public.account_is_active(auth.uid()));
CREATE TABLE public.invoice_customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), name text NOT NULL, data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.invoice_customers TO authenticated;
GRANT ALL ON public.invoice_customers TO service_role;
ALTER TABLE public.invoice_customers ENABLE ROW LEVEL SECURITY;
CREATE POLICY customer_own ON public.invoice_customers FOR ALL TO authenticated USING (user_id=auth.uid() AND public.account_is_active(auth.uid())) WITH CHECK (user_id=auth.uid() AND public.account_is_active(auth.uid()));
CREATE TABLE public.invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), number text NOT NULL DEFAULT '', prefix text NOT NULL DEFAULT 'INV-IMID-', customer_name text NOT NULL DEFAULT '', issue_date date NOT NULL DEFAULT CURRENT_DATE, due_date date, status text NOT NULL DEFAULT 'Draft', currency text NOT NULL DEFAULT 'USD', total numeric(14,2) NOT NULL DEFAULT 0, amount_paid numeric(14,2) NOT NULL DEFAULT 0, data jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,number));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.invoices TO authenticated;
GRANT ALL ON public.invoices TO service_role;
ALTER TABLE public.invoices ENABLE ROW LEVEL SECURITY;
CREATE POLICY invoices_own ON public.invoices FOR ALL TO authenticated USING (user_id=auth.uid() AND public.account_is_active(auth.uid())) WITH CHECK (user_id=auth.uid() AND public.account_is_active(auth.uid()));
CREATE INDEX invoices_owner_date ON public.invoices(user_id,issue_date DESC);
CREATE INDEX invoice_customers_owner ON public.invoice_customers(user_id);
CREATE INDEX invoice_businesses_owner ON public.invoice_businesses(user_id);
CREATE FUNCTION public.validate_invoice() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE seq integer; item jsonb; subtotal numeric:=0; discount_value numeric; discount numeric; tax numeric; extra numeric; qty numeric; rate numeric;
BEGIN
IF TG_OP='UPDATE' AND (NEW.user_id<>OLD.user_id OR NEW.number<>OLD.number) THEN RAISE EXCEPTION 'Invoice owner and number cannot be changed'; END IF;
IF NEW.prefix !~ '^[A-Za-z0-9-]{1,30}$' THEN RAISE EXCEPTION 'Invalid invoice prefix'; END IF;
IF NEW.status NOT IN ('Draft','Unpaid','Partially Paid','Paid','Overdue','Cancelled') OR NEW.currency NOT IN ('USD','ZAR','ZWG','EUR','GBP') THEN RAISE EXCEPTION 'Invalid invoice status or currency'; END IF;
IF octet_length(NEW.data::text)>150000 OR jsonb_typeof(NEW.data->'items') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.data->'items')>100 THEN RAISE EXCEPTION 'Invalid invoice items'; END IF;
FOR item IN SELECT * FROM jsonb_array_elements(NEW.data->'items') LOOP
qty:=(item->>'quantity')::numeric; rate:=(item->>'rate')::numeric;
IF qty IS NULL OR rate IS NULL OR qty<=0 OR qty>1000000 OR rate<0 OR rate>10000000 OR length(item->>'description')>500 OR length(item->>'details')>2000 THEN RAISE EXCEPTION 'Invalid line item'; END IF;
IF NEW.status<>'Draft' AND coalesce(trim(item->>'description'),'')='' THEN RAISE EXCEPTION 'Item descriptions are required'; END IF;
subtotal:=subtotal+round(qty*rate,2);
END LOOP;
discount_value:=coalesce((NEW.data->>'discount')::numeric,0); tax:=coalesce((NEW.data->>'tax')::numeric,0); extra:=coalesce((NEW.data->>'charges')::numeric,0);
IF discount_value<0 OR tax<0 OR tax>100 OR extra<0 OR NEW.amount_paid<0 THEN RAISE EXCEPTION 'Financial values cannot be negative'; END IF;
IF coalesce(NEW.data->>'discountType','percent')='percent' THEN IF discount_value>100 THEN RAISE EXCEPTION 'Discount cannot exceed 100 percent'; END IF; discount:=round(subtotal*discount_value/100,2); ELSE discount:=least(discount_value,subtotal); END IF;
NEW.total:=round((subtotal-discount)*(1+tax/100)+extra,2);
IF NEW.amount_paid>NEW.total THEN RAISE EXCEPTION 'Amount received cannot exceed total'; END IF;
IF NEW.status='Paid' AND NEW.amount_paid<>NEW.total THEN RAISE EXCEPTION 'Paid invoices must be paid in full'; END IF;
IF NEW.status<>'Draft' AND (trim(NEW.customer_name)='' OR jsonb_array_length(NEW.data->'items')=0) THEN RAISE EXCEPTION 'Customer and items are required'; END IF;
IF TG_OP='INSERT' THEN
INSERT INTO public.invoice_sequences(user_id,prefix,last_value) VALUES(NEW.user_id,NEW.prefix,1) ON CONFLICT(user_id,prefix) DO UPDATE SET last_value=invoice_sequences.last_value+1 RETURNING last_value INTO seq;
NEW.number:=NEW.prefix||lpad(seq::text,greatest(4,length(seq::text)),'0');
END IF;
NEW.updated_at:=now(); RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.validate_invoice() FROM PUBLIC;
CREATE TRIGGER invoice_validate BEFORE INSERT OR UPDATE ON public.invoices FOR EACH ROW EXECUTE FUNCTION public.validate_invoice();